/** Unified Gateway authority for Mahjong providers during legacy-runtime migration. */
public final class MahjongAuthoritativeSession implements AuthoritativeGameSession {
    private final long roomId, ownerId; private final int seatLimit; private final MahjongRuleFamily family; private final long seed; private final String playVersion; private final MahjongTileSet tileSet; private final boolean cd101;
    private final Map<Integer,Long> players=new LinkedHashMap<>(); private final java.util.Set<Integer> readySeats=new java.util.LinkedHashSet<>(); private final java.util.Set<Integer> continueSeats=new java.util.LinkedHashSet<>(); private MahjongState state;
    private MahjongRegionalRules.SettlementDetail lastSettlementDetail;
    private List<Integer> openingFlowers=List.of();
    private List<MahjongRegionalRules.ReplacementEvent> openingReplacements=List.of();
    private long stateVersion; private int roundNo;
    private final AuthoritativeTimeSource time=AuthoritativeTimeSource.systemUtc(); private final Duration operationTimeout=Duration.ofSeconds(20); private OperationDeadline operationDeadline=OperationDeadline.none(); private final OperationDeadlineArbiter deadlineArbiter=new OperationDeadlineArbiter();
    public MahjongAuthoritativeSession(long roomId,long ownerId,int seatLimit,long seed,MahjongRuleFamily family){this(roomId,ownerId,seatLimit,seed,family,"v1");}
    public MahjongAuthoritativeSession(long roomId,long ownerId,int seatLimit,long seed,MahjongRuleFamily family,String playVersion){this(roomId,ownerId,seatLimit,seed,family,playVersion,false);}
    MahjongAuthoritativeSession(long roomId,long ownerId,int seatLimit,long seed,MahjongRuleFamily family,String playVersion,boolean cd101){if(roomId<=0||ownerId<=0||seatLimit<2||seatLimit>4||playVersion==null||playVersion.isBlank())throw new IllegalArgumentException("invalid mahjong session");this.roomId=roomId;this.ownerId=ownerId;this.seatLimit=seatLimit;this.seed=seed;this.family=java.util.Objects.requireNonNull(family);this.playVersion=playVersion;this.tileSet=family.tileSet(playVersion);this.cd101=cd101;}
    public static MahjongAuthoritativeSession restore(Map<String,Object> saved,MahjongRuleFamily family){return restore(saved,family,false);}
    static MahjongAuthoritativeSession restore(Map<String,Object> saved,MahjongRuleFamily family,boolean cd101){long room=longValue(saved.get("roomId"));long owner=longValue(saved.get("ownerId"));long seed=longValue(saved.get("seed"));Map<Integer,Long> restoredPlayers=longMap(saved.get("players"));int limit=Math.max(2,number(saved,"seatLimit",Math.max(2,restoredPlayers.size())));String version=String.valueOf(saved.getOrDefault("playVersion","v1"));MahjongAuthoritativeSession session=new MahjongAuthoritativeSession(room,owner,limit,seed,family,version,cd101);session.players.putAll(restoredPlayers);session.readySeats.addAll(numbers(saved.get("readySeats")));session.continueSeats.addAll(numbers(saved.get("continueSeats")));Object raw=saved.get("state");if(raw instanceof MahjongState mahjongState)session.state=mahjongState;else if(raw instanceof Map<?,?> map)session.state=restoreState(map);session.roundNo=number(saved,"roundNo",session.state==null?0:1);session.stateVersion=saved.get("stateVersion")instanceof Number n?n.longValue():0;session.openingFlowers=numbers(saved.get("openingFlowers"));session.openingReplacements=restoreReplacements(saved.get("openingReplacements"));session.operationDeadline=OperationDeadline.from(saved.get("operationDeadline"));Object detail=saved.get("settlementDetail");if(detail instanceof MahjongRegionalRules.SettlementDetail settlementDetail)session.lastSettlementDetail=settlementDetail;else if(detail instanceof Map<?,?>map)session.lastSettlementDetail=restoreSettlementDetail(map);return com.aoo.bcg.gamespi.fsm.RestoredAuthorityValidator.requireConsistent(session);}
    @Override public synchronized GameCommandResult execute(GameCommandRequest r){validateCommandContext(r);long player=player(r.authenticatedUserId());Map<String,Object> body;String op=leaf(r.msgId());switch(op){
        case "join"->{if(state!=null)throw new IllegalStateException("round started");if(r.seatId()>=seatLimit||players.containsKey(r.seatId())||players.containsValue(player))throw new IllegalStateException("seat/player occupied");players.put(r.seatId(),player);body=viewFor(player);}
        case "ready"->{requireSeat(player,r.seatId());if(state!=null)throw new IllegalStateException("round started");readySeats.add(r.seatId());body=viewFor(player);}
        case "start"->{if(player!=ownerId)throw new SecurityException("owner only");start();body=viewFor(player);}
        case "state"->body=viewFor(player);
        case "exchange"->{requireSeat(player,r.seatId());requireOpeningPhase(false);MahjongRegionalRules.OpeningSelections selections=state.openingSelections().submitExchange(r.seatId(),state.hands().get(r.seatId()),numbers(r.body().get("tiles")));Map<Integer,List<Integer>>hands=state.hands();if(selections.exchanges().keySet().equals(players.keySet()))hands=selections.applyExchange(players.keySet().stream().sorted().toList(),hands,1);state=state.replaceAll(state.wall(),hands,state.currentSeat(),state.currentSeatHasDrawn(),state.lastDiscard(),state.lastDiscardSeat(),state.window(),false,-1,state.melds(),state.winners(),state.lastDrawnTile(),selections);body=viewFor(player);}
        case "dingque"->{requireSeat(player,r.seatId());requireOpeningPhase(true);MahjongSuit suit=com.aoo.bcg.gamespi.StrictEnumDecoder.byName(MahjongSuit.class,String.valueOf(r.body().get("suit")).toUpperCase(java.util.Locale.ROOT));MahjongRegionalRules.OpeningSelections selections=state.openingSelections().submitMissingSuit(r.seatId(),suit);state=state.replaceAll(state.wall(),state.hands(),state.currentSeat(),state.currentSeatHasDrawn(),state.lastDiscard(),state.lastDiscardSeat(),state.window(),false,-1,state.melds(),state.winners(),state.lastDrawnTile(),selections);body=viewFor(player);}
        default->{requireSeat(player,r.seatId());if(state==null)throw new IllegalStateException("round not started");MahjongOperation operation=com.aoo.bcg.gamespi.StrictEnumDecoder.byName(MahjongOperation.class,op.toUpperCase(java.util.Locale.ROOT));if(cd101&&operation==MahjongOperation.CHI)throw new IllegalArgumentException("CD101 does not allow chi");if(openingPending())completeOpeningByTimeout();int tile=number(r.body(),"tile",0);int gangType=0;if(cd101&&operation==MahjongOperation.GANG){if(!r.body().containsKey("stateVersion")||longValue(r.body().get("stateVersion"))!=stateVersion)throw new IllegalStateException("stale gang candidate");gangType=number(r.body(),"type",0);tile=number(r.body(),"mahjongId",0);if(!gangCandidates(r.seatId()).contains(new GangCandidate(gangType,tile)))throw new IllegalStateException("gang candidate is not available");}List<Integer> consumed=cd101&&gangType==2?List.of(tile,tile,tile):numbers(r.body().get("consumedTiles"));state=new MahjongCoreEngine().execute(state,new MahjongCommand(r.seatId(),operation,tile,consumed,gangType),family.ruleSet());body=viewFor(player);}
    }if(!op.equals("state")&&!op.equals("hint"))stateVersion=Math.addExact(stateVersion,1);if(state!=null&&!state.finished()&&!op.equals("state")&&!op.equals("hint"))operationDeadline=OperationDeadline.open(op,state.currentSeat(),operationTimeout,time);if(state!=null&&state.finished())operationDeadline=OperationDeadline.none();return new GameCommandResult(r.msgId().replace("_req","_resp"),r.requestId(),body);}
    @Override public synchronized long stateVersion(){return stateVersion;}
    private void start(){if(state!=null||players.size()<2)throw new IllegalStateException("cannot start");startRound(1);}
    synchronized ContinueRoundResult continueRound(long player,int seat){requireSeat(player,seat);if(state==null||!state.finished())throw new IllegalStateException("round not settled");if(!continueSeats.add(seat))return new ContinueRoundResult(false,false);boolean allConfirmed=continueSeats.containsAll(players.keySet());if(allConfirmed)startRound(Math.addExact(roundNo,1));stateVersion=Math.addExact(stateVersion,1);return new ContinueRoundResult(true,allConfirmed);}
    private void startRound(int nextRound){List<Integer> wall=new ArrayList<>(tileSet.createWall());long roundSeed=Math.addExact(seed,nextRound-1L);new SeededGameRandomSource(roundSeed).shuffle(wall);List<Integer>seats=players.keySet().stream().sorted().toList();MahjongRegionalRules.DealerPolicy dealerPolicy=new MahjongRegionalRules.DealerPolicy(true,true);int dealer=dealerPolicy.initialDealer(seats,0);MahjongRegionalRules.DealResult dealt=MahjongRegionalRules.deal(tileSet,wall,seats,dealer,13,!tileSet.flowerTiles().isEmpty());openingFlowers=dealt.flowers();openingReplacements=dealt.replacements();lastSettlementDetail=null;continueSeats.clear();roundNo=nextRound;state=new MahjongState(dealt.wall(),dealt.hands(),dealer,true,-1,-1,MahjongOperationWindow.empty(),false,-1);operationDeadline=OperationDeadline.open("start",dealer,operationTimeout,time);}
    private boolean openingPending(){return family.ruleSet().requireOpeningSelections()&&(state.openingSelections().exchanges().size()<players.size()||state.openingSelections().missingSuits().size()<players.size());}
    private void completeOpeningByTimeout(){MahjongRegionalRules.OpeningSelections selections=state.openingSelections();List<Integer>seats=players.keySet().stream().sorted().toList();for(int seat:seats)selections=selections.timeoutExchange(seat,state.hands().get(seat));Map<Integer,List<Integer>>hands=selections.applyExchange(seats,state.hands(),1);for(int seat:seats)selections=selections.timeoutMissingSuit(seat,hands.get(seat));state=state.replaceAll(state.wall(),hands,state.currentSeat(),state.currentSeatHasDrawn(),state.lastDiscard(),state.lastDiscardSeat(),state.window(),false,-1,state.melds(),state.winners(),state.lastDrawnTile(),selections);}
    private void requireOpeningPhase(boolean missingSuit){if(state==null||!family.ruleSet().requireOpeningSelections())throw new IllegalStateException("opening selection is unavailable");boolean exchangesDone=state.openingSelections().exchanges().keySet().equals(players.keySet());if(missingSuit!=exchangesDone)throw new IllegalStateException(missingSuit?"exchange selections are incomplete":"exchange phase is complete");}
    synchronized java.util.Set<Integer> continueSeats(){return java.util.Set.copyOf(continueSeats);} synchronized int roundNo(){return roundNo;} record ContinueRoundResult(boolean changed,boolean roundStarted){}
    synchronized void validateCommandContext(GameCommandRequest request){if(request.roomId()!=roomId||!playVersion.equals(request.playVersion()))throw new IllegalArgumentException("command roomId/playVersion mismatch");}
    @Override public synchronized Map<String,Object> viewFor(long viewer){Integer own=seatOf(viewer);Map<Integer,Object> seats=new LinkedHashMap<>();for(var e:players.entrySet()){List<Integer> cards=state==null?List.of():state.hands().get(e.getKey());seats.put(e.getKey(),Map.of("playerId",e.getValue(),"cards",e.getKey().equals(own)||(state!=null&&state.finished())?cards:Collections.nCopies(cards.size(),0),"cardCount",cards.size()));}List<Map<String,Object>>replacementView=openingReplacements.stream().map(event->Map.<String,Object>of("seat",event.seat(),"flowerTile",event.flowerTile(),"replacementTile",event.seat()==(own==null?-1:own)||state!=null&&state.finished()?event.replacementTile():0)).toList();Map<String,Object> out=new LinkedHashMap<>();out.put("roomId",roomId);out.put("family",family.familyCode());out.put("started",state!=null);out.put("currentSeat",state==null?-1:state.currentSeat());out.put("currentSeatHasDrawn",state!=null&&state.currentSeatHasDrawn());out.put("lastDiscard",state==null?-1:state.lastDiscard());out.put("legalActions",legalActions(own));if(cd101)out.put("gangCandidates",own==null?List.of():gangCandidates(own).stream().map(c->Map.of("type",c.type(),"mahjongId",c.mahjongId())).toList());out.put("finished",state!=null&&state.finished());out.put("winnerSeat",state==null?-1:state.winnerSeat());out.put("winners",state==null?List.of():state.winners().stream().sorted().toList());out.put("openingPhase",state==null?"WAITING":!family.ruleSet().requireOpeningSelections()?"PLAYING":state.openingSelections().exchanges().size()<players.size()?"EXCHANGE":state.openingSelections().missingSuits().size()<players.size()?"DINGQUE":"PLAYING");out.put("openingSelections",state==null?Map.of():cd101?publicOpeningSelections():state.openingSelections().snapshot());out.put("openingFlowers",openingFlowers);out.put("openingReplacements",replacementView);out.put("seats",Map.copyOf(seats));return Map.copyOf(out);}
    private List<String> legalActions(Integer own){
        if(own==null||state==null||state.finished()||openingPending())return List.of();
        if(!state.window().isEmpty())return state.window().candidates().getOrDefault(own,java.util.Set.of()).stream().filter(op->!cd101||op!=MahjongOperation.CHI).map(Enum::name).sorted().toList();
        if(state.currentSeat()!=own)return List.of();
        if(!state.currentSeatHasDrawn())return List.of("DRAW");
        List<String> actions=new ArrayList<>();actions.add("DISCARD");if(cd101&&!gangCandidates(own).isEmpty())actions.add("GANG");
        if(family.ruleSet().canWin(own,state.hands().get(own),state.lastDrawnTile(),state))actions.add("HU");
        return List.copyOf(actions);
    }
    private record GangCandidate(int type,int mahjongId){}
    private Map<String,Object> publicOpeningSelections(){
        Map<Integer,Boolean> exchanges=new java.util.TreeMap<>();
        Map<Integer,Boolean> missingSuits=new java.util.TreeMap<>();
        for(int seat:players.keySet()){
            exchanges.put(seat,state.openingSelections().exchanges().containsKey(seat));
            missingSuits.put(seat,state.openingSelections().missingSuits().containsKey(seat));
        }
        return Map.of("exchanges",Map.copyOf(exchanges),"missingSuits",Map.copyOf(missingSuits));
    }
    private List<GangCandidate> gangCandidates(int seat){
        if(!cd101||state==null||state.finished()||openingPending()||!state.hands().containsKey(seat))return List.of();
        List<Integer> hand=state.hands().get(seat);
        if(!state.window().isEmpty()){
            int tile=state.lastDiscard();
            return state.window().allows(seat,MahjongOperation.GANG)
                    && Collections.frequency(hand,tile)>=3?List.of(new GangCandidate(2,tile)):List.of();
        }
        if(state.currentSeat()!=seat||!state.currentSeatHasDrawn())return List.of();
        List<GangCandidate> result=new ArrayList<>();
        state.melds().getOrDefault(seat,List.of()).stream().filter(m->m.operation()==MahjongOperation.PENG)
                .map(m->m.tiles().get(0)).distinct().sorted().filter(hand::contains)
                .forEach(tile->result.add(new GangCandidate(3,tile)));
        hand.stream().distinct().sorted().filter(tile->Collections.frequency(hand,tile)>=4)
                .forEach(tile->result.add(new GangCandidate(4,tile)));
        return List.copyOf(result);
    }
    @Override public synchronized Map<String,Object> authoritativeState(){Map<String,Object>out=new LinkedHashMap<>();out.put("roomId",roomId);out.put("ownerId",ownerId);out.put("seatLimit",seatLimit);out.put("seed",seed);out.put("playVersion",playVersion);out.put("tileSetSize",tileSet.size());out.put("players",Map.copyOf(players));out.put("readySeats",List.copyOf(readySeats));out.put("continueSeats",List.copyOf(continueSeats));out.put("roundNo",roundNo);out.put("state",state==null?"WAITING":state);out.put("openingFlowers",openingFlowers);out.put("openingReplacements",openingReplacements);out.put("operationDeadline",operationDeadline.toMap());out.put("stateVersion",stateVersion);if(lastSettlementDetail!=null)out.put("settlementDetail",lastSettlementDetail);return Map.copyOf(out);}
    @Override public synchronized OperationDeadline operationDeadline(){return operationDeadline;}
    @Override public OperationDeadlineArbiter deadlineArbiter(){return deadlineArbiter;}
    @Override public synchronized List<String> invariantViolations(){List<String>errors=new ArrayList<>();if(new java.util.HashSet<>(players.values()).size()!=players.size())errors.add("DUPLICATE_PLAYER");if(state!=null){if(!players.keySet().equals(state.hands().keySet()))errors.add("SEAT_HAND_MISMATCH");if(!state.hands().containsKey(state.currentSeat()))errors.add("CURRENT_SEAT_MISSING");List<Integer>allTiles=java.util.stream.Stream.of(state.wall().stream(),state.hands().values().stream().flatMap(List::stream),state.melds().values().stream().flatMap(List::stream).flatMap(m->m.tiles().stream()),openingFlowers.stream()).flatMap(s->s).toList();errors.addAll(tileSet.inventoryViolations(allTiles));if(state.hands().values().stream().flatMap(List::stream).anyMatch(tileSet::isFlower))errors.add("FLOWER_IN_HAND");}return List.copyOf(errors);}
    @Override public synchronized SettlementPayload settlement(int roundNo,String requestedPlayVersion){if(!playVersion.equals(requestedPlayVersion))throw new IllegalArgumentException("settlement playVersion mismatch");if(state==null||!state.finished())throw new IllegalStateException("round not finished");List<MahjongRegionalRules.SettlementLine>lines=new ArrayList<>();if(cd101){int fengDing=0;int baseUnit=MahjongRegionRulePolicies.baseUnit(Map.of());/* 登记：待开房规则字段接入；session未保存createRules，按终裁c采用最保守fengDing=0，baseUnit走策略默认1。 */lines.addAll(CDXZFanScoring.settleCd101(state,fengDing,baseUnit));}else for(int winner:state.winners())for(int seat:players.keySet())if(!state.winners().contains(seat))lines.add(new MahjongRegionalRules.SettlementLine(seat,winner,1,"WIN","AUTHORITATIVE_ROUND"));lastSettlementDetail=MahjongRegionalRules.settle(new ArrayList<>(players.keySet()),lines);Map<Long,Long>deltas=new LinkedHashMap<>();lastSettlementDetail.totals().forEach((seat,delta)->deltas.put(players.get(seat),delta));return new SettlementPayload(roomId,roundNo,playVersion,deltas);}
    private void requireSeat(long player,int seat){if(!Long.valueOf(player).equals(players.get(seat)))throw new SecurityException("seat not owned");}private Integer seatOf(long player){return players.entrySet().stream().filter(e->e.getValue()==player).map(Map.Entry::getKey).findFirst().orElse(null);}private static long player(String s){try{long v=Long.parseLong(s);if(v<=0)throw new NumberFormatException();return v;}catch(NumberFormatException e){throw new IllegalArgumentException("invalid player id");}}private static String leaf(String id){String value=id.substring(id.lastIndexOf('.')+1);return value.endsWith("_req")?value.substring(0,value.length()-4):value;}private static int number(Map<String,Object>b,String k,int fallback){Object v=b.get(k);return v instanceof Number n?n.intValue():fallback;}private static List<Integer> numbers(Object value){if(!(value instanceof List<?> list))return List.of();return list.stream().map(v->{if(!(v instanceof Number n))throw new IllegalArgumentException("numeric cards required");return n.intValue();}).toList();}
    private static MahjongState restoreState(Map<?,?> m){List<Integer>wall=numbers(m.get("wall"));Map<Integer,List<Integer>>hands=intListMap(m.get("hands"));int current=intValue(m.get("currentSeat"));Map<Integer,java.util.Set<MahjongOperation>>candidates=new LinkedHashMap<>();Object rawWindow=m.get("window");if(rawWindow instanceof Map<?,?>w){Object rawCandidates=w.get("candidates");if(rawCandidates instanceof Map<?,?>cm)cm.forEach((k,v)->{java.util.Set<MahjongOperation>ops=new java.util.LinkedHashSet<>();if(v instanceof List<?>l)l.forEach(x->ops.add(com.aoo.bcg.gamespi.StrictEnumDecoder.byName(MahjongOperation.class,String.valueOf(x))));candidates.put(intValue(k),ops);});}Map<Integer,List<MahjongState.Meld>>melds=restoreMelds(m.get("melds"));java.util.Set<Integer>winners=new java.util.LinkedHashSet<>(numbers(m.get("winners")));int winner=intValue(m.get("winnerSeat"));if(winners.isEmpty()&&winner>=0)winners.add(winner);MahjongRegionalRules.OpeningSelections selections=m.get("openingSelections")instanceof Map<?,?>raw?MahjongRegionalRules.OpeningSelections.restore(stringMap(raw)):MahjongRegionalRules.OpeningSelections.empty();return new MahjongState(wall,hands,current,booleanValue(m.get("currentSeatHasDrawn")),intValue(m.get("lastDiscard")),intValue(m.get("lastDiscardSeat")),new MahjongOperationWindow(candidates),booleanValue(m.get("finished")),winner,melds,winners,numberMap(m,"lastDrawnTile",0),selections);}
    private static Map<Integer,List<MahjongState.Meld>>restoreMelds(Object raw){Map<Integer,List<MahjongState.Meld>>out=new LinkedHashMap<>();if(raw instanceof Map<?,?>map)map.forEach((key,value)->{List<MahjongState.Meld>items=new ArrayList<>();if(value instanceof List<?>list)for(Object item:list){if(item instanceof MahjongState.Meld meld)items.add(meld);else if(item instanceof Map<?,?>m)items.add(new MahjongState.Meld(com.aoo.bcg.gamespi.StrictEnumDecoder.byName(MahjongOperation.class,String.valueOf(m.get("operation"))),numbers(m.get("tiles")),intValue(m.get("sourceSeat"))));}out.put(intValue(key),List.copyOf(items));});return out;}
    private static Map<String,Object>stringMap(Map<?,?>raw){Map<String,Object>out=new LinkedHashMap<>();raw.forEach((k,v)->out.put(String.valueOf(k),v));return out;}private static int numberMap(Map<?,?>map,String key,int fallback){Object value=map.get(key);return value==null?fallback:intValue(value);}
    private static Map<Integer,Long>longMap(Object value){Map<Integer,Long>out=new LinkedHashMap<>();if(value instanceof Map<?,?>m)m.forEach((k,v)->out.put(intValue(k),longValue(v)));return out;}private static Map<Integer,List<Integer>>intListMap(Object value){Map<Integer,List<Integer>>out=new LinkedHashMap<>();if(value instanceof Map<?,?>m)m.forEach((k,v)->out.put(intValue(k),numbers(v)));return out;}private static int intValue(Object v){return v instanceof Number n?n.intValue():Integer.parseInt(String.valueOf(v));}private static long longValue(Object v){return v instanceof Number n?n.longValue():Long.parseLong(String.valueOf(v));}private static boolean booleanValue(Object v){return v instanceof Boolean b?b:Boolean.parseBoolean(String.valueOf(v));}
    private static MahjongRegionalRules.SettlementDetail restoreSettlementDetail(Map<?,?>map){ArrayList<MahjongRegionalRules.SettlementLine>lines=new ArrayList<>();Object rawLines=map.get("lines");if(rawLines instanceof List<?>list)for(Object raw:list){if(!(raw instanceof Map<?,?>line))throw new IllegalArgumentException("invalid settlement detail");lines.add(new MahjongRegionalRules.SettlementLine(intValue(line.get("payer")),intValue(line.get("receiver")),longValue(line.get("points")),String.valueOf(line.get("category")),String.valueOf(line.get("source"))));}Map<Integer,Long>expected=longMap(map.get("totals"));MahjongRegionalRules.SettlementDetail detail=MahjongRegionalRules.settle(new ArrayList<>(expected.keySet()),lines);if(!detail.totals().equals(expected))throw new IllegalArgumentException("settlement totals mismatch");return detail;}
    private static List<MahjongRegionalRules.ReplacementEvent>restoreReplacements(Object raw){if(!(raw instanceof List<?>list))return List.of();return list.stream().map(value->{Map<?,?>m=(Map<?,?>)value;return new MahjongRegionalRules.ReplacementEvent(intValue(m.get("seat")),intValue(m.get("flowerTile")),intValue(m.get("replacementTile")));}).toList();}
}
